{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));

  try {
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 30000 });
    await w(1000);
    const eInp = await page.$('#email_principal');
    if (eInp) { await eInp.click(); await eInp.type(EMAIL, { delay: 20 }); }
    await w(500);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
    await page.waitForSelector('#pwdInput', { timeout: 10000 });
    const sInp = await page.$('#pwdInput');
    if (sInp) { await sInp.click(); await sInp.type(SENHA, { delay: 20 }); }
    await w(500);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
    await w(4000);
    await page.evaluate(() => { const img = document.querySelector('img[src*=\"hapvida\"]'); if(img) { const p = img.closest('.clickable-element') || img.parentElement.parentElement; if(p) p.click(); } });
    await w(2000);

    // FORM
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 30000 });
    await w(2000);
    await page.evaluate(() => { const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); if(p) p.click(); });
    await w(1500);
    await page.waitForSelector('#id-nomelead', { timeout: 8000 });
    const nInp = await page.$('#id-nomelead');
    if (nInp) { await nInp.click(); await nInp.type('teste', { delay: 15 }); }
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Avan')); if(b) b.click(); });
    await w(2000);

    // CIDADE
    await page.waitForSelector('#cidade_nome', { timeout: 8000 });
    const cInp = await page.$('#cidade_nome');
    if (cInp) { await cInp.click(); await cInp.type('teresina', { delay: 50 }); }
    await w(1500);
    const tCoords = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { if (el.textContent.trim() === 'Teresina - PI') { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (tCoords) await page.mouse.click(tCoords.x, tCoords.y);
    await w(1000);
    try { await page.select('select.Dropdown', '\"mei___empres_rio_individual\"'); } catch(e) {}
    await w(800);

    // AVANCAR 2
    const b2 = await page.$$('button');
    for (const btn of b2) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn); if (i.t && i.t.includes('Avan') && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(2000);

    // FAIXAS
    await page.evaluate(() => { document.querySelectorAll('input').forEach(inp => { const r = inp.getBoundingClientRect(); const s = window.getComputedStyle(inp); if (r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) { inp.focus(); inp.value = '1'; inp.dispatchEvent(new Event('input', { bubbles: true })); inp.dispatchEvent(new Event('change', { bubbles: true })); } }); });
    await w(1000);

    // AVANCAR 3
    const b3 = await page.$$('button');
    for (const btn of b3) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn); if (i.t && i.t.includes('Avan') && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(2000);

    // ADD PRODUTOS
    const b4 = await page.$$('button');
    for (const btn of b4) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent.trim(), d: s.display, v: s.visibility }; }, btn); if (i.t === 'Add Produtos' && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(2000);

    // HAPVIDA
    const hCoords = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { if (el.textContent.trim() === 'Hapvida') { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (hCoords) await page.mouse.click(hCoords.x, hCoords.y);
    await w(2000);

    // TABELA
    const tabCoords = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim(); if (t.includes('Teresina') && t.includes('2') && t.includes('29')) { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (tabCoords) await page.mouse.click(tabCoords.x, tabCoords.y);
    await w(1500);

    // AMBULATORIAL
    const aCoords = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { if (el.textContent.trim() === 'Ambulatorial') { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (aCoords) await page.mouse.click(aCoords.x, aCoords.y);
    await w(1500);

    // ACOMODACAO
    const acCoords = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim().toLowerCase(); if (t.includes('sem acomodação') && t.includes('coparticipação')) { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (acCoords) await page.mouse.click(acCoords.x, acCoords.y);
    await w(1500);

    // FECHA MODAL
    await page.mouse.click(1200, 400);
    await w(2000);

    // EXTRAI
    const faixas = await page.evaluate(() => { const nomes = ['0 a 18 anos','19 a 23 anos','24 a 28 anos','29 a 33 anos','34 a 38 anos','39 a 43 anos','44 a 48 anos','49 a 53 anos','54 a 58 anos','59 anos ou mais']; const vals = []; const regex = /^\d{2,3}[,.]\d{2}$/; document.querySelectorAll('div, span').forEach(el => { const s = window.getComputedStyle(el); const r = el.getBoundingClientRect(); if (s.display !== 'none' && r.width > 0 && el.textContent.length < 15) { const t = el.textContent.trim(); if (regex.test(t) && !vals.some(v => v.text === t) && r.y > 650 && r.x > 150 && r.x < 280) { vals.push({ text: t, y: r.y }); } } }); vals.sort((a,b) => a.y - b.y); return vals.slice(0,10).map((v,i) => ({ faixa_etaria: nomes[i], valor: 'R$ ' + v.text.replace('.',',') })); });

    const screenshot = await page.screenshot({ encoding: 'base64' });
    const pageText = await page.evaluate(() => document.body.innerText.substring(0, 800));

    return { success: true, faixas, screenshot, pageText };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, screenshot };
  }
}"
}
